#!/usr/bin/env python3
"""Apply WP-0018: program-bot workflows, pr_report.py, docs."""
import base64
import os

REPO = "."
FILES = {
    '.github/workflows/program-status.yml': "",
    '.github/workflows/ci.yml': "",
    '.github/workflows/program.yml': "",
    'program/tools/pr_report.py': "",
    'program/tools/test_pr_report.py': "",
    'program/AGENT-PROFILES.md': "",
    'program/BRIEFING.md': "",
    'program/RAID.md': "",
    'program/decisions/ADR-0004-owner-decisions-2026-10-16.md': "",
    'program/work/P0/WP-0018-tracker-upkeep-and-test-feedback-for-ais-without-a-shell.md': "",
}

def main():
    for path, b64 in FILES.items():
        full = os.path.join(REPO, path)
        os.makedirs(os.path.dirname(full), exist_ok=True)
        with open(full, "w", encoding="utf-8") as f:
            f.write(base64.b64decode(b64).decode("utf-8"))
        print("wrote", path)

if __name__ == "__main__":
    main()
